WITH valid AS (SELECT *, TRIM(country) AS clean_country, CONCAT_WS('/', device, country) AS device_country_key FROM sessions WHERE browser IN ('Firefox', 'Chrome', 'Safari')), eligible AS (SELECT s.* FROM valid s WHERE NOT EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.event_time <= s.started_at)), with_windows AS (SELECT *, FIRST_VALUE(country) IGNORE NULLS OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at DESC, id) AS row_seq, FIRST_VALUE(country, TRUE) OVER w_hist AS first_known_country_2 FROM eligible WHERE customer_id IN (13, 18, 21, 30) WINDOW w_hist AS (PARTITION BY browser, device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), latest_match AS (SELECT s.*, x.web_event_event_type, x.web_event_page FROM with_windows s LEFT JOIN LATERAL (SELECT c.event_type AS web_event_event_type, c.page AS web_event_page FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, browser, country, clean_country, device_country_key, first_known_country, row_seq, web_event_page, CASE WHEN browser RLIKE '^(Safari|Chrome)$' THEN 'OTHER_ZONE' WHEN browser RLIKE '^(Firefox|Edge)$' THEN 'CORE' ELSE 'PRIORITY' END AS browser_zone FROM latest_match ORDER BY row_seq DESC
